PRAGMA foreign_keys = ON;

BEGIN TRANSACTION;

INSERT INTO core_publication
  (publication_type, pmid, authors, title, journal, publication_date, url,
   contains_promoter_data, contains_expression_data, submission_notes, curation_complete,
   reported_TF, reported_species)
SELECT
  'ARTICLE',
  '42347962',
  'Kılıç G, Gökmen GG, Mishra YK',
  'Eco-friendly synthesis of ZnO nanostructures from yeast strains isolated from kombucha and beetroot kwass for antimicrobial thin film applications.',
  'Bioprocess and biosystems engineering',
  '2026 Jun 25',
  'https://doi.org/10.1007/s00449-026-03372-0',
  0,
  1,
  'Grand test',
  1,
  'VsrD',
  'Vibrio vulnificus MO6-24/O'
WHERE NOT EXISTS (
  SELECT 1 FROM core_publication WHERE pmid='42347962'
);

UPDATE core_publication
SET
  authors = CASE WHEN authors IS NULL OR authors='' THEN 'Kılıç G, Gökmen GG, Mishra YK' ELSE authors END,
  title = CASE WHEN title IS NULL OR title='' THEN 'Eco-friendly synthesis of ZnO nanostructures from yeast strains isolated from kombucha and beetroot kwass for antimicrobial thin film applications.' ELSE title END,
  journal = CASE WHEN journal IS NULL OR journal='' THEN 'Bioprocess and biosystems engineering' ELSE journal END,
  publication_date = CASE WHEN publication_date IS NULL OR publication_date='' THEN '2026 Jun 25' ELSE publication_date END,
  url = CASE WHEN url IS NULL OR url='' THEN 'https://doi.org/10.1007/s00449-026-03372-0' ELSE url END,
  reported_TF = CASE WHEN reported_TF IS NULL OR reported_TF='' THEN 'VsrD' ELSE reported_TF END,
  reported_species = CASE WHEN reported_species IS NULL OR reported_species='' THEN 'Vibrio vulnificus MO6-24/O' ELSE reported_species END,
  contains_promoter_data = 0,
  contains_expression_data = 1,
  curation_complete = 1,
  submission_notes = CASE
    WHEN submission_notes IS NULL OR submission_notes='' THEN 'Grand test'
    ELSE submission_notes
  END
WHERE pmid='42347962';

INSERT INTO core_tf (name, family_id, description)
SELECT 'VsrD', 2, 'A response regulator [PFAM::PF00072] of the LuxR family in Ralstonia solanacearum involved in regulation of exopolysaccharide synthesis [PMID::9573161].'
WHERE NOT EXISTS (
  SELECT 1 FROM core_tf WHERE lower(name)=lower('VsrD')
);

UPDATE core_tf
SET
  family_id = COALESCE(family_id, 2),
  description = CASE WHEN description IS NULL THEN 'A response regulator [PFAM::PF00072] of the LuxR family in Ralstonia solanacearum involved in regulation of exopolysaccharide synthesis [PMID::9573161].' ELSE description END
WHERE lower(name)=lower('VsrD');

INSERT INTO core_tfinstance (refseq_accession, uniprot_accession, description, TF_id, notes)
SELECT
  'WP_003536762',
  'Q92LT2',
  'HpdR  [Sinorhizobium meliloti 1021].',
  (SELECT TF_id FROM core_tf WHERE lower(name)=lower('VsrD') LIMIT 1),
  ''
WHERE NOT EXISTS (
  SELECT 1 FROM core_tfinstance WHERE uniprot_accession='Q92LT2'
);

UPDATE core_tfinstance
SET
  TF_id = COALESCE(TF_id, (SELECT TF_id FROM core_tf WHERE lower(name)=lower('VsrD') LIMIT 1)),
  refseq_accession = COALESCE(NULLIF(refseq_accession,''), 'WP_003536762'),
  description = COALESCE(NULLIF(description,''), 'HpdR  [Sinorhizobium meliloti 1021].'),
  notes = COALESCE(notes, '')
WHERE uniprot_accession='Q92LT2';

INSERT INTO core_curation
  (TF_species, site_species, experimental_process, forms_complex,
   complex_notes, notes, last_modified, curator_id, publication_id, created, validated_by_id)
VALUES
  ('Vibrio vulnificus MO6-24/O', 'Vibrio vulnificus MO6-24/O', NULL,
   0, NULL, 'Grand test',
   datetime('now'), (SELECT curator_id FROM core_curator ORDER BY curator_id LIMIT 1), (SELECT publication_id FROM core_publication WHERE pmid='42347962' LIMIT 1), datetime('now'), NULL);

INSERT INTO core_curation_TF_instances (curation_id, tfinstance_id)
SELECT (SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='42347962' LIMIT 1) ORDER BY curation_id DESC LIMIT 1), (SELECT TF_instance_id FROM core_tfinstance WHERE uniprot_accession='Q92LT2' LIMIT 1)
WHERE NOT EXISTS (
  SELECT 1 FROM core_curation_TF_instances
  WHERE curation_id=(SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='42347962' LIMIT 1) ORDER BY curation_id DESC LIMIT 1) AND tfinstance_id=(SELECT TF_instance_id FROM core_tfinstance WHERE uniprot_accession='Q92LT2' LIMIT 1)
);

